              <span className="bar l"><i className="c0" style={{ width: (tally[k][0] / peak) * 100 + '%' }} /></span>
              <span className="k">{k}</span>
              <span className="bar r"><i className="c1" style={{ width: (tally[k][1] / peak) * 100 + '%' }} /></span>
