window.__geo = () => {
  const nav = document.querySelector('.nav').offsetHeight, stage = document.querySelector('.stage');
  return [...document.querySelectorAll('.step')].map((st) => {
    // the place a reader naturally stops: the step's top right under the pinned replay
    const y = st.getBoundingClientRect().top + scrollY - nav - stage.offsetHeight;
    window.scrollTo({ top: y, behavior: 'instant' });
    const sb = stage.getBoundingClientRect().bottom, h3 = st.querySelector('.h3').getBoundingClientRect().top, end = st.lastElementChild.getBoundingClientRect().bottom;
    const nx = st.nextElementSibling && st.nextElementSibling.querySelector && st.nextElementSibling.querySelector('.h3');
    return `${innerWidth}x${innerHeight} ${st.dataset.mode}: player ends ${Math.round(sb)}, title ${Math.round(h3)}, text ends ${Math.round(end)}, next title ${nx ? Math.round(nx.getBoundingClientRect().top) : '-'}, snap ${getComputedStyle(document.documentElement).scrollSnapType}`;
  });
};
({ pin: getComputedStyle(document.documentElement).getPropertyValue('--pin-h'), tour: !!document.querySelector('.tour'), geo: __geo() })

const out = [];
for (const [w, h] of [[320, 568], [360, 640], [375, 667], [390, 844]]) {
  const f = document.createElement('iframe'); f.style.cssText = `position:absolute;left:-9999px;top:0;width:${w}px;height:${h}px;border:0`; f.src = location.href; document.body.appendChild(f);
  await new Promise(r => f.onload = r); await new Promise(r => setTimeout(r, 1800));
  const W = f.contentWindow, d = f.contentDocument, nav = d.querySelector('.nav').offsetHeight, stage = d.querySelector('.stage');
  const hud = d.querySelector('.stage-hud');
  const rows = [...d.querySelectorAll('.step')].map((st) => {
    W.scrollTo({ top: st.getBoundingClientRect().top + W.scrollY - nav - stage.offsetHeight, behavior: 'instant' });
    return `${st.dataset.mode} title ${Math.round(st.querySelector('.h3').getBoundingClientRect().top)} > player ${Math.round(stage.getBoundingClientRect().bottom)}, text ends ${Math.round(st.lastElementChild.getBoundingClientRect().bottom)}/${h}`;
  });
  out.push({ size: `${w}x${h}`, hudOverflow: hud.scrollWidth - hud.clientWidth, rows });
  f.remove();
}
